def should_bypass_proxy(host: str, port: int, no_proxy: str) -> bool:
    h = host.lower()
    for raw in no_proxy.split(','):
        entry = raw.strip().lower()
        if not entry:
            continue
        if entry == '*':
            return True
        if ':' in entry:
            e_host, e_port = entry.rsplit(':', 1)
            if int(e_port) != port:
                continue
            entry = e_host
        clean = entry.lstrip('*.')
        if h == clean or h.endswith('.' + clean):
            return True
    return False

