def allocate_widths(total: int, ratios: list[int], min_width: int = 1) -> list[int]:
    s = sum(ratios)
    exact = [max(float(min_width), total * r / s) for r in ratios]
    floored = [max(min_width, int(x)) for x in exact]
    diff = total - sum(floored)
    remainders = sorted(range(len(ratios)), key=lambda i: (exact[i] - floored[i]), reverse=True)
    for idx in remainders:
        if diff == 0:
            break
        if diff > 0:
            floored[idx] += 1
            diff -= 1
        elif floored[idx] > min_width:
            floored[idx] -= 1
            diff += 1
    return floored

