import re
def sort_pdb_residues(res_ids: list[str]) -> list[str]:
    def _key(r: str) -> tuple[int, str]:
        m = re.match(r'^(-?\d+)([A-Za-z]*)$', r.strip())
        if not m:
            raise ValueError(f'Invalid residue ID: {r}')
        return (int(m.group(1)), m.group(2))
    return sorted(res_ids, key=_key)
